svg.script:
(function(){
var fo=document.getElementById('fo'),r=document.getElementById('aero-root'),s=document.documentElement,X='http://www.w3.org/1999/xhtml';
function fit(){var w=innerWidth,h=innerHeight;if(w>0&&h>0){fo.setAttribute('width',w);fo.setAttribute('height',h)}}
fit();addEventListener('resize',fit);
document.createElement=function(n){return document.createElementNS(X,String(n).toLowerCase())};
try{Object.defineProperty(document,'body',{configurable:true,get:function(){return r}});Object.defineProperty(document,'head',{configurable:true,get:function(){return r}})}catch(e){}
function load(src){return new Promise(function(res,rej){var t=document.createElementNS(X,'script');t.onload=res;t.onerror=function(){rej(new Error('Failed to load '+src))};t.src=src;r.appendChild(t)})}
/* The service worker (sw.js, next to this file) serves Scramjet/BareMux/Epoxy as virtual files, so register it first */
window.__aeroBoot=async function(B){
  if(location.protocol==='file:')throw new Error('The proxy needs this SVG hosted on http(s) with sw.js next to it (service workers cannot run from file://).');
  if(!('serviceWorker' in navigator))throw new Error('Service workers are not supported in this browser');
  await navigator.serviceWorker.register(B+'sw.js',{scope:B});
  await navigator.serviceWorker.ready;
  if(!navigator.serviceWorker.controller)await new Promise(function(r){navigator.serviceWorker.addEventListener('controllerchange',r,{once:true});setTimeout(r,4000)});
  if(!navigator.serviceWorker.controller)throw new Error('Service worker installed. Reload this page once to finish setup.');
  if(!window.BareMux)await load(B+'baremux/index.js');
  if(!window.$scramjetLoadController)await load(B+'scram/scramjet.all.js');
};
})();
